/// A player as shown in search results and as "mi jugador".
class PlayerSummary {
  const PlayerSummary({
    required this.id,
    required this.alias,
    this.lastActivity,
  });

  /// Public id generated by the API; the player shares it to be found.
  final String id;
  final String alias;

  /// Null when the player has an account but has not sent any match yet.
  final DateTime? lastActivity;

  @override
  bool operator ==(Object other) =>
      other is PlayerSummary &&
      other.id == id &&
      other.alias == alias &&
      other.lastActivity == lastActivity;

  @override
  int get hashCode => Object.hash(id, alias, lastActivity);
}
